for (const clause of CLAUSES) {
  const faqs = CLAUSE_FAQS[clause.slug]
  if (faqs) {
    clause.faqs = faqs
  }
}

const ALL_CLAUSES = [...CLAUSES]
export const INDEXABLE_CLAUSES = filterRetainedSeoItems('clauses', ALL_CLAUSES)

// ─── Lookup Functions ────────────────────────────────────────────────

export function getClauseBySlug(slug: string): LeaseClause | undefined {
  return ALL_CLAUSES.find((c) => c.slug === slug)
}

export function getAllClauseSlugs(): string[] {
  return ALL_CLAUSES.map((c) => c.slug)
}

export function getIndexableClauseBySlug(slug: string): LeaseClause | undefined {
  return INDEXABLE_CLAUSES.find((c) => c.slug === slug)
}

export function getAllIndexableClauseSlugs(): string[] {
  return INDEXABLE_CLAUSES.map((c) => c.slug)
}

export function getClausesByCategory(category: LeaseClause['category']): LeaseClause[] {
  return INDEXABLE_CLAUSES.filter((c) => c.category === category)
}


// ─── Publication date ───────────────────────────────────────────────
export const CLAUSES_PUBLISHED_AT = '2026-03-18'
/** ISO date of the last significant content update to this file. Update when data changes. */
export const CLAUSES_LAST_UPDATED = '2026-04-06'

export function getClauseSeoRedirect(slug: string): string | null {
  if (isRetainedSeoSlug('clauses', slug)) return null
  if (!ALL_CLAUSES.some((clause) => clause.slug === slug)) return null
  return getExplicitSeoRedirect('clauses', slug) ?? '/clauses'
}
